def normalize_marketplace_data(apps, schema_editor):
    Publicacion = apps.get_model('marketplace', 'PublicacionMarket')
    Oferta = apps.get_model('marketplace', 'Oferta')

    for publication in Publicacion.objects.all():
        target = publication.pieza_inventario or publication.coleccion_usuario
        publication.vendedor_id = target.user_id
        publication.estado = publication.estado.upper()
        if publication.estado not in {'ACTIVA', 'RESERVADA', 'VENDIDA', 'CANCELADA'}:
            publication.estado = 'ACTIVA'
        publication.save(update_fields=['vendedor', 'estado'])

    allowed_offer_states = {'PENDIENTE', 'ACEPTADA', 'RECHAZADA', 'COMPLETADA', 'CANCELADA'}
    for offer in Oferta.objects.all():
        offer.estado = offer.estado.upper()
        if offer.estado not in allowed_offer_states:
            offer.estado = 'PENDIENTE'
        offer.save(update_fields=['estado'])


